// Canonical URL form used for dedupe (spec §5.2).
//
// This file is the single source of truth: scripts/build-wf20.js inlines the
// function body into WF-20's Canonicalize node, so the tests in
// tests/canonicalize.test.js exercise exactly what runs in production.
//
// No URL/URLSearchParams — the n8n task-runner sandbox has neither.

// `src` joins the list for the same reason as `source`: it is overwhelmingly a
// referrer tag (?src=twitter), and leaving it in split one page into two feed
// items during testing.
const STRIP = /^(utm_.*|fbclid|gclid|ref|source|src|mc_cid|mc_eid|igshid)$/i;

// Every YouTube URL shape for one video (watch?v=, youtu.be/, shorts/, embed/,
// live/, m. and music. hosts) collapses to one key, with pp/si/t/list dropped:
// otherwise the same video pasted twice became two feed items.
const YT_ID = /^(?:https?:\/\/)?(?:(?:www|m|music)\.)?(?:youtube\.com\/(?:watch\?(?:[^#]*&)?v=|shorts\/|embed\/|live\/|v\/)|youtu\.be\/)([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])/i;
function youtubeId(rawUrl) {
  const m = String(rawUrl || '').trim().match(YT_ID);
  return m ? m[1] : null;
}

function canon(rawUrl) {
  try {
    const yt = youtubeId(rawUrl);
    if (yt) return 'https://www.youtube.com/watch?v=' + yt;
    const s = String(rawUrl).trim();
    const m = s.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/);
    if (!m) return null;
    const scheme = m[1].toLowerCase();
    let hostport = m[2];
    let path = m[3] || '/';
    const query = m[4] ? m[4].slice(1) : '';
    let userinfo = '';
    const at = hostport.lastIndexOf('@');
    if (at !== -1) { userinfo = hostport.slice(0, at + 1); hostport = hostport.slice(at + 1); }
    let host = hostport;
    let port = '';
    const ci = hostport.lastIndexOf(':');
    if (ci !== -1 && /^\d+$/.test(hostport.slice(ci + 1))) { host = hostport.slice(0, ci); port = hostport.slice(ci); }
    host = host.toLowerCase();
    if (host.startsWith('amp.')) host = host.slice(4);
    if ((scheme === 'http' && port === ':80') || (scheme === 'https' && port === ':443')) port = '';
    path = path.replace(/\/amp(\/|$)/, '$1');
    path = path.replace(/\/{2,}/g, '/');
    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
    if (!path) path = '/';
    const params = query ? query.split('&').filter(p => p !== '' && !STRIP.test(p.split('=')[0])) : [];
    const qs = params.length ? '?' + params.join('&') : '';
    return scheme + '://' + userinfo + host + port + path + qs;
  } catch (e) { return null; }
}

const j = $input.first().json;
let items = [];
try { items = JSON.parse(j.items_json || '[]'); } catch (e) {}
const out = items.map((m) => ({ url: m.url, canonical_url: canon(m.url) || m.url, slides: Boolean(m.slides), transcribe: Boolean(m.transcribe) }));
if (!out.length) return [];
const esc = (u) => String(u).replace(/'/g, "''");
const query = "select coalesce(json_object_agg(f.canonical_url, json_build_object('id', f.id, 'title', f.title, 'summary', f.summary, 'score', f.score, " +
  "'canonical_url', f.canonical_url, 'key_points', f.structured->'key_points', 'transcript_source', substr(d.scraper, 7))), '{}')::text as stored " +
  "from feed_items f join raw_docs d on d.id = f.raw_doc_id where d.scraper like 'media:%' and f.canonical_url in (" +
  out.map((o) => "'" + esc(o.canonical_url) + "'").join(',') + ")";
return [{ json: { items: out, trigger: j.trigger || 'agent', query } }];

const s = $('Items').first().json;
let stored = {};
try { stored = JSON.parse($input.first().json.stored || '{}'); } catch (e) {}
return s.items.map((it) => {
  const have = stored[it.canonical_url];
  const reuse = Boolean(have) && !it.slides && !it.transcribe;
  return { json: { ...it, reuse, stored: reuse ? have : null, trigger: s.trigger } };
});

// Media links (YouTube, podcasts, audio) in WF-20: detection, the transcript
// markdown that triage reads, the key-points skill, and the Telegram message.
// Inlined into WF-20 Code nodes; tests/media.test.js covers it.
//
// The transcript itself comes from media/server.py (native on Windows):
// human captions -> auto-captions -> Parakeet speech-to-text.

// Hosts yt-dlp handles that carry talk worth summarising. Direct audio files
// count too (a podcast episode's enclosure URL).
const MEDIA_HOST = /^https?:\/\/(?:[a-z0-9-]+\.)*(?:youtube\.com|youtu\.be|vimeo\.com|soundcloud\.com|podcasts\.apple\.com|twitch\.tv|ted\.com\/talks|rumble\.com)(?:[\/?#]|$)/i;
const AUDIO_FILE = /\.(mp3|m4a|aac|wav|ogg|opus|flac|mp4|webm)(\?|#|$)/i;
// YouTube pages that are not one video (channels, playlists, search) are not media items
const YT_NOT_VIDEO = /youtube\.com\/(?:@|c\/|channel\/|user\/|playlist|results|feed)/i;

function isMediaUrl(url) {
  const u = String(url || '').trim();
  if (!/^https?:\/\//i.test(u) || YT_NOT_VIDEO.test(u)) return false;
  return MEDIA_HOST.test(u) || AUDIO_FILE.test(u.split('?')[0] + (u.includes('?') ? '?' : ''));
}

// One Telegram message -> every link in it (n >= 1, in order, deduped) plus
// the trigger words Wasim chose (2026-10-11):
//   slides | deck | presentation | watch | look  -> also read the screen
//   transcribe | listen | hear                   -> speech-to-text on the audio
// Links are cut out before matching: "watch" is in every youtube.com/watch URL.
const SLIDE_WORDS = /\b(slides?|decks?|presentations?|watch(ing)?|look(ing)?)\b/i;
const TRANSCRIBE_WORDS = /\b(transcribe|transcription|listen(ing)?|hear(ing)?)\b/i;
// A short no-link reply asking for the audio ("transcribe", "yes transcribe it")
// after the bot said a video has no captions. The router hands it to WF-42
// before the model runs — the 9B answered a bare "transcribe" without calling
// the tool (2026-10-11). Anchored, so a question that merely mentions
// transcribing stays chat. "transcribe slides" / "slides and transcribe" also
// reads the screen (WF-42 picks the slide word up from the same message).
const BARE_MEDIA_REPLY = /^\s*(?:(?:yes|yeah|yep|ok|okay|sure|please|pls|go ahead(?: and)?)[\s,!.]*)*(?:(?:the\s+)?(?:slides?|decks?|presentations?|screen)[\s,]+(?:(?:and|with|\+)\s+)?)?(?:transcribe|transcription|listen|hear)(?:[\s,]+(?:it|this|that|the video|to it|please|pls|now|and|with|\+|(?:the\s+)?(?:slides?|decks?|presentations?|screen)))*[\s.!]*$/i;
function parseMediaRequest(text, extraUrl) {
  const raw = String(text || '');
  const found = raw.match(/https?:\/\/[^\s<>"')\]]+/gi) || [];
  if (extraUrl && /^https?:\/\//i.test(String(extraUrl).trim())) found.push(String(extraUrl).trim());
  const seen = new Set();
  const urls = [];
  for (let u of found) {
    u = u.replace(/[.,;:!?]+$/, '');
    if (!seen.has(u)) { seen.add(u); urls.push(u); }
  }
  const words = raw.replace(/https?:\/\/[^\s<>"')\]]+/gi, ' ');
  return { urls, slides: SLIDE_WORDS.test(words), transcribe: TRANSCRIBE_WORDS.test(words) };
}

function mmss(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  const p = (n) => String(n).padStart(2, '0');
  return h ? h + ':' + p(m) + ':' + p(sec) : m + ':' + p(sec);
}

// "1:02:05" / "12:30" / "45" -> seconds, or null
function parseTs(t) {
  const m = String(t == null ? '' : t).trim().replace(/^\[|\]$/g, '').match(/^(?:(\d+):)?(\d{1,2}):(\d{2})$|^(\d+)$/);
  if (!m) return null;
  if (m[4] != null) return Number(m[4]);
  return Number(m[1] || 0) * 3600 + Number(m[2]) * 60 + Number(m[3]);
}

const SOURCE_LABEL = { 'captions-manual': 'creator captions', 'captions-auto': 'YouTube auto-captions', parakeet: 'speech-to-text (Parakeet)' };

// What triage reads: a header the model can cite, then [m:ss] paragraphs.
function mediaMarkdown(t) {
  const lines = [];
  lines.push('# ' + (t.title || 'Untitled'));
  const meta = [t.channel && 'Channel: ' + t.channel, t.duration && 'Length: ' + mmss(t.duration),
    t.published_at && 'Published: ' + t.published_at, 'Transcript: ' + (SOURCE_LABEL[t.source] || t.source)].filter(Boolean);
  lines.push(meta.join(' | '));
  // the media service's auto-look verdict; Compose summary reads it back for the footer
  if (t.screen_note) lines.push('Screen: ' + t.screen_note);
  if (t.chapters && t.chapters.length) {
    lines.push('', '## Chapters');
    for (const c of t.chapters) lines.push('[' + mmss(c.start) + '] ' + c.title);
  }
  if (t.slides && t.slides.length) {
    lines.push('', '## On screen (slides, charts, code; machine-read from video frames, may contain misreads)');
    for (const s of t.slides) lines.push('[' + mmss(s.start) + '] ' + s.text);
  }
  lines.push('', '## Transcript');
  for (const p of t.paragraphs || []) lines.push('[' + mmss(p.start) + '] ' + p.text);
  return lines.join('\n');
}

// Merged into the triage call for media documents (same mechanism as query skills).
const MEDIA_SKILL_PROMPT =
  'This CONTENT is a timestamped transcript of a video or podcast. Lines start with [m:ss]. ' +
  'In addition to the standard fields, return key_points: 6 to 12 of the most important, concrete points ' +
  '(claims, numbers, names, decisions, how-tos), in the order they are made. For each, t is the [m:ss] timestamp ' +
  'of the transcript line where it is made, copied exactly from the transcript (never invented), and point is one ' +
  'self-contained sentence. Prefer specifics over generalities; skip intros, sponsor reads and calls to subscribe. ' +
  'The On screen section is machine-read from video frames: use it for figures and names shown on slides, but when it ' +
  'disagrees with what is said in the transcript, trust the transcript.';
const MEDIA_SKILL_SCHEMA = {
  key_points: { type: 'array', items: { type: 'object', additionalProperties: false,
    properties: { t: { type: 'string' }, point: { type: 'string' } }, required: ['t', 'point'] } }
};

// Link that opens the video at a moment. YouTube only; other hosts get none.
function timeLink(canonicalUrl, seconds) {
  const m = String(canonicalUrl || '').match(/youtube\.com\/watch\?v=([A-Za-z0-9_-]{11})/);
  return m ? 'https://youtu.be/' + m[1] + '?t=' + Math.floor(seconds) : null;
}

// The 9B gets the facts right but approximates timestamps (measured on the IBM
// video: 2 of 4 checked points pointed at the wrong moment, one at a time that
// is not in the transcript). Snap each point to the transcript line that shares
// the most words with it, preferring lines near the model's guess; keep the
// model's time when nothing matches well.
const STOP = new Set(['the', 'and', 'for', 'that', 'this', 'with', 'are', 'was', 'from', 'they', 'you', 'have', 'has',
  'its', 'into', 'than', 'then', 'their', 'there', 'which', 'what', 'when', 'will', 'can', 'not', 'but', 'more', 'about', 'each']);
const words = (s) => new Set(String(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter((w) => (w.length >= 3 || /\d/.test(w)) && !STOP.has(w)));

function transcriptLines(markdown) {
  const out = [];
  const body = String(markdown || '').split('## Transcript')[1] || '';
  for (const line of body.split('\n')) {
    const m = line.match(/^\[(\d+(?::\d{2}){1,2})\]\s*(.*)$/);
    if (m) out.push({ start: parseTs(m[1]), words: words(m[2]) });
  }
  return out;
}

function snapKeyPoints(points, markdown) {
  const lines = transcriptLines(markdown);
  if (!lines.length || !Array.isArray(points)) return points || [];
  // Measured on the IBM video's 10 points: the model's own times 4/10 right;
  // best-overlap snapping 8/10 right + 1 off by one 30s paragraph. (Trusting
  // the model's time whenever it names a real line scored worse: 1:58 and
  // 7:49 are real lines that share generic words with the wrong points.)
  return points.map((p) => {
    const pw = words(p.point);
    const guess = parseTs(p.t);
    let best = null, bestScore = 0;
    for (const l of lines) {
      let overlap = 0;
      for (const w of pw) if (l.words.has(w)) overlap++;
      const near = guess == null ? 0 : Math.max(0, 1 - Math.abs(l.start - guess) / 120) * 0.5;
      const score = overlap + near;
      if (score > bestScore) { bestScore = score; best = l; }
    }
    // need real lexical evidence (>= 3 shared words) to override the model
    if (best && bestScore >= 3) return { t: mmss(best.start), point: p.point };
    return { t: guess == null ? p.t : mmss(guess), point: p.point };
  });
}

// Telegram (HTML parse mode) message for one summarised media item.
function mediaMessage(item) {
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const head = '\u{1F3AC} <b>' + esc(item.title) + '</b>' + (item.score != null ? '  (score ' + item.score + '/10)' : '');
  const out = [head];
  if (item.summary) out.push('', esc(item.summary));
  const pts = Array.isArray(item.key_points) ? item.key_points : [];
  if (pts.length) {
    out.push('', '<b>Key points</b>');
    for (const p of pts) {
      const sec = parseTs(p.t);
      const link = sec == null ? null : timeLink(item.canonical_url, sec);
      const stamp = sec == null ? '' : (link ? '<a href="' + link + '">' + mmss(sec) + '</a> ' : mmss(sec) + ' ');
      out.push('• ' + stamp + esc(p.point));
    }
  }
  const via = [item.transcript_source && 'from ' + (SOURCE_LABEL[item.transcript_source] || item.transcript_source), item.screen].filter(Boolean);
  if (via.length) out.push('', '<i>' + esc(via.join(' · ')) + '</i>');
  return out.join('\n').slice(0, 4000);   // Telegram's limit is 4096
}

// 👍/👎 feedback: the Telegram buttons, reading a tap, and turning the votes
// into calibration examples for triage (sql/013).
//
// callback_data is "fb:<vote>:<feed_item_id>" — the item id, not the list
// number, so a tap on an old message still rates the right item after the
// chat has moved on to another list. Telegram caps callback_data at 64 bytes.

const UP = '\u{1F44D}';
const DOWN = '\u{1F44E}';
const CHOSEN = '✅';

function itemKeyboard(id) {
  const n = Number(id);
  if (!Number.isInteger(n) || n <= 0) return null;
  return { inline_keyboard: [[{ text: UP, callback_data: 'fb:1:' + n }, { text: DOWN, callback_data: 'fb:-1:' + n }]] };
}

// A numbered list: "1 👍" "1 👎" "2 👍" "2 👎" — two items per row, first 10 items.
function listKeyboard(items, max = 10) {
  const ok = (items || []).filter((i) => i && Number.isInteger(Number(i.id)) && Number(i.id) > 0 && i.n != null).slice(0, max);
  if (!ok.length) return null;
  if (ok.length === 1) return itemKeyboard(ok[0].id);
  const rows = [];
  for (let k = 0; k < ok.length; k += 2) {
    rows.push(ok.slice(k, k + 2).flatMap((i) => [
      { text: i.n + ' ' + UP, callback_data: 'fb:1:' + Number(i.id) },
      { text: i.n + ' ' + DOWN, callback_data: 'fb:-1:' + Number(i.id) }]));
  }
  return { inline_keyboard: rows };
}

function parseVote(data) {
  const m = String(data || '').match(/^fb:(-?1):(\d+)$/);
  return m ? { vote: Number(m[1]), id: Number(m[2]) } : null;
}

// The same keyboard with the tapped choice ticked (and the item's other button un-ticked).
function votedKeyboard(markup, id, vote) {
  if (!markup || !Array.isArray(markup.inline_keyboard)) return null;
  const strip = (t) => String(t).replace(' ' + CHOSEN, '');
  return { inline_keyboard: markup.inline_keyboard.map((row) => row.map((b) => {
    const v = parseVote(b.callback_data);
    if (!v || v.id !== Number(id)) return b;
    return { ...b, text: strip(b.text) + (v.vote === vote ? ' ' + CHOSEN : '') };
  })) };
}

// Which items did this reply show? The query_feed / get_item results in the
// agent's tool steps (or the guard's prefetch), as {n, id}. Observations can
// be JSON strings or objects, possibly wrapped — walk whatever comes back.
function shownItems(sources) {
  const found = new Map();
  const visit = (x, depth) => {
    if (x == null || depth > 8) return;
    if (typeof x === 'string') {
      const s = x.trim();
      if (s[0] === '{' || s[0] === '[') { try { visit(JSON.parse(s), depth + 1); } catch (e) {} }
      return;
    }
    if (Array.isArray(x)) { x.forEach((y) => visit(y, depth + 1)); return; }
    if (typeof x !== 'object') return;
    if (x.n != null && Number(x.id) > 0 && (x.title || x.canonical_url)) found.set(Number(x.n), { n: Number(x.n), id: Number(x.id) });
    for (const k of Object.keys(x)) if (k !== 'structured') visit(x[k], depth + 1);
  };
  visit(sources, 0);
  return [...found.values()].sort((a, b) => a.n - b.n);
}

// Few-shot calibration for triage. rows: [{vote, title, summary}], newest
// first. Empty string when there is nothing to show, so triage is unchanged
// until the first tap.
function tasteBlock(rows, perSide = 6) {
  const list = Array.isArray(rows) ? rows : [];
  const line = (r) => '- ' + String(r.title || '').trim().slice(0, 120) +
    (r.summary ? ' — ' + String(r.summary).replace(/\s+/g, ' ').trim().slice(0, 160) : '');
  const liked = list.filter((r) => Number(r.vote) === 1).slice(0, perSide).map(line);
  const disliked = list.filter((r) => Number(r.vote) === -1).slice(0, perSide).map(line);
  if (!liked.length && !disliked.length) return '';
  const out = ['', '', "WASIM'S RATINGS OF PAST FEED ITEMS (newest first)",
    'He tapped these in Telegram. Use them to calibrate angle_strength and specificity for items LIKE them —',
    'they show what he finds useful or useless beyond the written beat. They never override the beat, and an',
    'item unlike any of them is scored on the beat alone.'];
  if (liked.length) out.push('Liked (' + UP + '):', ...liked);
  if (disliked.length) out.push('Disliked (' + DOWN + '):', ...disliked);
  return out.join('\n');
}

// The rows tasteBlock reads: latest 6 likes + latest 6 dislikes, newest first,
// as JSON text. A scalar subquery, so it drops into any SELECT or RETURNING.
const TASTE_SQL = "(select coalesce(json_agg(t order by t.updated_at desc), '[]')::text from (" +
  "(select fb.vote, fb.updated_at, f.title, left(f.summary, 160) as summary from feedback fb join feed_items f on f.id = fb.feed_item_id where fb.vote = 1 order by fb.updated_at desc limit 6) " +
  "union all " +
  "(select fb.vote, fb.updated_at, f.title, left(f.summary, 160) as summary from feedback fb join feed_items f on f.id = fb.feed_item_id where fb.vote = -1 order by fb.updated_at desc limit 6)) t)";

return { json: { text: '\u{1F4DA} Already in your feed:\n\n' + mediaMessage($json.stored), reply_markup: itemKeyboard($json.stored.id) } };

// "summarize the video without the timestamps" (2026-10-18): the router read
// "summarize" as a big-picture question and WF-45 wrote an overview of every
// feed item with "video" in it (an n8n tutorial, a Mod Sun music video...).
// Three gaps, fixed together:
//   1. messages sent outside the agent (WF-20 media/link summaries, WF-43
//      re-sends) never reached chat memory or chat_results, so "the video" had
//      nothing to point at -> botSaidSql records every such send;
//   2. keyword routes (synth) ran before anyone asked whether the message points
//      at something already shown -> refRoute runs first, in code;
//   3. "without the timestamps" had nowhere to go -> itemBody/itemAnswer rewrite
//      the one item as asked, from its own text only, figure-checked.
// Inlined into WF-00 (routing, answer), WF-20 and WF-43 (recording).
// Needs unsupportedFacts from answer-check.js inlined first (itemAnswer only).

// things the bot shows one of; plurals ("the videos about agents") are topics
const REF_NOUN = '(?:video|clip|talk|podcast|episode|article|story|item|link|page|piece|post|paper|report|thread|interview|one|result|transcript)';
// "the video", "that article", "this one", "the last link"
const REF_PHRASE = new RegExp('\\b(?:the|that|this|your|ur)\\s+(?:last\\s+|latest\\s+|previous\\s+|same\\s+)?' + REF_NOUN + '\\b(?![-\'’]?s\\b)', 'i');
// ...followed by a description: may be a search, so the agent decides
const REF_DESCRIBED = new RegExp(REF_PHRASE.source + '\\s+(?:about|on|from|by|with|where|that|which|called|titled|named)\\b', 'i');
// "summarize it", "what does it say", "tell me more about that"
const REF_PRONOUN = new RegExp([
  '\\b(?:summari[sz]e|recap|explain|shorten|simplify|rewrite|redo|reformat|translate|tl;?dr|break down|go over|unpack)\\s+(?:it|this|that)\\b',
  '\\bwhat (?:does|did|is) (?:it|this|that) (?:say|said|cover|mean|about|argue|claim|conclude)',
  '\\b(?:more|tell me|anything else) (?:more )?(?:about|on) (?:it|this|that)\\b',
  // whole-message only: "is it worth it to switch to X" is a question of its own
  '^(?:so |and |but )?(?:is|was) (?:it|this|that) (?:worth (?:it|watching|reading|a look)|any good|legit|accurate)\\s*[?.!]*$',
].join('|'), 'i');
// a bare instruction with nothing else in it: "summarize without timestamps", "shorter please"
const TRANSFORM_VERB = /^(?:can you |could you |please |pls |now |ok(?:ay)?,? )*(summari[sz]e|recap|shorten|simplify|rewrite|redo|reformat|tl;?dr|summary|shorter|simpler|briefer|again)\b/i;
const FORMAT_WORDS = /\b(?:without|with|no|minus|skip|drop|remove|the|a|an|any|all|in|into|as|to|of|for|me|just|only|please|pls|it|this|that|again|version|summary|plain|simple|simpler|short|shorter|brief|briefly|quick|quickly|english|text|prose|paragraphs?|bullets?|bullet points?|points?|lines?|sentences?|words?|timestamps?|time ?stamps?|times|links?|emojis?|numbers?|formatting|one|two|three|four|five|\d+)\b/gi;

// What the message points at, from its words alone:
//   'bare'      - one shown thing, no description ("summarize the video", "is it any good?")
//   'described' - a shown thing picked by description ("the article about nvidia")
//   ''          - not a reference; normal routing
function referentKind(text) {
  const t = String(text || '').trim();
  if (!t || /https?:\/\//i.test(t)) return '';
  if (REF_DESCRIBED.test(t)) return 'described';
  if (REF_PHRASE.test(t) || REF_PRONOUN.test(t)) return 'bare';
  const m = TRANSFORM_VERB.exec(t);
  if (m && !t.slice(m[0].length).replace(FORMAT_WORDS, ' ').replace(/[^a-z]+/gi, ' ').trim()) return 'bare';
  return '';
}

// the last list shown counts for this long
const REF_WINDOW_MIN = 120;

const MEDIA_NOUN = /\b(?:video|clip|talk|podcast|episode|interview|transcript)\b/i;
const MEDIA_URL = /youtube\.com\/watch|youtu\.be\/|vimeo\.com|soundcloud\.com|podcasts\.apple\.com|twitch\.tv|ted\.com\/talks|rumble\.com/i;

// The route, given the last list this chat was shown (chat_results, with each
// item's title and url in list order):
//   { route: 'item', n }  - it can only mean item n: answered here, in code
//                           (one item shown, or "the video" and one video shown)
//   { route: 'agent' }    - several fit: the agent picks with get_item, told the list
//   { route: '' }         - no reference, or nothing recent to refer to
function refRoute(text, list) {
  const kind = referentKind(text);
  const l = list || {};
  const items = Array.isArray(l.items) ? l.items : [];
  const n = Number(l.n) || items.length;
  const age = Number(l.age_min);
  if (!kind || !n || !(age >= 0 && age <= REF_WINDOW_MIN)) return { route: '' };
  if (kind === 'bare' && n === 1) return { route: 'item', n: 1 };
  if (kind === 'bare' && MEDIA_NOUN.test(text)) {
    const vids = items.map((it, k) => ({ k: k + 1, media: MEDIA_URL.test(String(it.url || '')) })).filter((x) => x.media);
    if (vids.length === 1) return { route: 'item', n: vids[0].k };
  }
  return { route: 'agent' };
}

// what the agent is told on the 'agent' route: the list itself (memory may not
// hold it: a WF-31 list is in memory only as the reply text, if at all)
function refNote(list) {
  const items = (list && Array.isArray(list.items) ? list.items : []).slice(0, 10);
  return '[This message points at something already shown in this chat. The last list shown: ' +
    (items.map((it, k) => (k + 1) + '. ' + String(it.title || it.url || '').slice(0, 120)).join('; ') || 'unknown') +
    '. If the message means one of these, call get_item with its number (never query_feed for it) and follow any format instruction in the message (shorter, no timestamps, bullets). If it fits none, ask which one they mean.]';
}

// Telegram HTML -> what he read, for memory
function plainText(html) {
  return String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').trim();
}

// One message the bot sent outside the agent: an ai memory row tagged with its
// source (Fix memory and the sweep check skip tagged rows: a video can arrive
// while an answer is being written), and, when it showed items, the chat's
// numbered list, so "#1" / "the video" resolve to it. base64 keeps web text out
// of the SQL (CLAUDE.md: '$785606.5' breaks the Postgres node).
function botSaidSql(chatId, html, itemIds, source) {
  const chat = String(chatId || '').trim();
  const text = plainText(html);
  if (!/^-?\d+$/.test(chat) || !text) return 'select 1 as skipped';
  const b64 = Buffer.from(text, 'utf8').toString('base64');
  const src = String(source || 'system').replace(/[^a-z0-9_-]/gi, '');
  const ids = (itemIds || []).map(Number).filter((x) => Number.isInteger(x) && x > 0);
  const mem = "insert into n8n_chat_histories (session_id, message) values ('" + chat + "', jsonb_build_object('type', 'ai', 'content', " +
    "convert_from(decode('" + b64 + "', 'base64'), 'UTF8'), 'tool_calls', '[]'::jsonb, 'invalid_tool_calls', '[]'::jsonb, " +
    "'additional_kwargs', jsonb_build_object('source', '" + src + "'), 'response_metadata', '{}'::jsonb))";
  if (!ids.length) return mem + ' returning id';
  return 'with m as (' + mem + ' returning id) ' +
    'insert into chat_results (chat_id, item_ids, topic, created_at) values (' + chat + ', array[' + ids.join(',') + ']::bigint[], null, now()) ' +
    'on conflict (chat_id) do update set item_ids = excluded.item_ids, topic = excluded.topic, created_at = excluded.created_at returning (select id from m) as id';
}

// SQL filter for "rows the agent wrote" (untagged)
const AGENT_ROWS = "coalesce(message->'additional_kwargs'->>'source', '') = ''";

// the item's own words: summary, key points (times dropped), page text
function itemText(item) {
  const it = item || {};
  const pts = ((it.structured || {}).key_points || it.key_points || []).map((p) => '- ' + (p.point || p)).join('\n');
  return [it.title && 'Title: ' + it.title, it.summary && 'Summary: ' + it.summary, pts && 'Key points:\n' + pts,
    it.page_excerpt && 'Saved text (excerpt):\n' + String(it.page_excerpt).slice(0, 6000)].filter(Boolean).join('\n\n');
}

const ITEM_SYSTEM = 'You answer a request about ONE item the user was just shown (an article or video from their research feed). ' +
  'Use ONLY the item text given. Follow the request\'s format instructions exactly (e.g. no timestamps, shorter, bullets, plain prose). ' +
  'Never add facts, names or numbers that are not in the item text; if it does not say, say so. ' +
  'Plain text, no markdown, no timestamps unless asked. Start with the answer, not with "Sure".';

// LM Studio body, thinking off (reasoning_effort none: CLAUDE.md, Models)
function itemBody(model, request, item) {
  return { model, temperature: 0, reasoning_effort: 'none', max_tokens: 900,
    messages: [{ role: 'system', content: ITEM_SYSTEM },
      { role: 'user', content: 'Request: ' + String(request || '') + '\n\nItem:\n' + itemText(item) }] };
}

// the stored summary with its points, no times: the answer when the 9B's fails
function plainSummary(item) {
  const it = item || {};
  const pts = ((it.structured || {}).key_points || it.key_points || []).map((p) => String(p.point || p).trim()).filter(Boolean);
  return [String(it.title || '').trim(), String(it.summary || '').trim(), pts.length ? 'Key points:\n' + pts.map((p) => '• ' + p).join('\n') : '']
    .filter(Boolean).join('\n\n');
}

// the 9B's answer if it holds up against the item, else the stored summary
function itemAnswer(content, item, request) {
  let out = String(content || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const reason = !out ? 'empty' : unsupportedFacts(out, itemText(item), request).length ? 'unsupported figures' : '';
  if (reason) out = plainSummary(item);
  return { output: out || "I couldn't open that item again. Ask about it by name and I'll search the feed.", fallback: reason };
}

